<?php
declare(strict_types=1);
session_start();
require_once __DIR__.'/../app/Helpers/Database.php';require_once __DIR__.'/../app/Helpers/Auth.php';require_once __DIR__.'/../app/Helpers/Response.php';
use SAMS\Helpers\Database;use SAMS\Helpers\Auth;use SAMS\Helpers\Response;
header('Content-Type: application/json; charset=UTF-8');
try{$u=Auth::requireLogin();$pdo=Database::connection();$classId=(int)($_GET['class_id']??0);$month=(string)($_GET['month']??'');if($classId<1||!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month))Response::error('Invalid report parameters.',422);$access=in_array($u['role'],['admin','counselor'],true)?$pdo->prepare('SELECT name FROM classes WHERE id=? AND is_active=1'):$pdo->prepare('SELECT c.name FROM classes c JOIN teacher_classes tc ON tc.class_id=c.id WHERE c.id=? AND c.is_active=1 AND tc.teacher_id=?');$access->execute(in_array($u['role'],['admin','counselor'],true)?[$classId]:[$classId,$u['id']]);$className=$access->fetchColumn();if($className===false)Response::error('Forbidden.',403);$start=$month.'-01';$end=date('Y-m-t',strtotime($start));$q=$pdo->prepare('SELECT s.id,s.student_number,s.first_name,s.last_name,COALESCE(SUM(a.status=\'present\'),0) present_count,COALESCE(SUM(a.status=\'absent\'),0) absent_count,COALESCE(SUM(a.status IN (\'late\',\'excused\')),0) other_count,COUNT(a.id) recorded_count FROM students s LEFT JOIN attendance a ON a.student_id=s.id AND a.attendance_date BETWEEN ? AND ? WHERE s.class_id=? AND s.status=\'active\' GROUP BY s.id,s.student_number,s.first_name,s.last_name ORDER BY s.last_name,s.first_name');$q->execute([$start,$end,$classId]);Response::success(['class_name'=>$className,'month'=>$month,'students'=>$q->fetchAll()]);}catch(Throwable $e){error_log('[SAMS reports] '.$e->getMessage());Response::error('Server error.',500);}
